package dev.civcraftreborn.client;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

/**
 * Construction guide, not an autogenerated prefab. Minecraft blocks must be
 * placed by a player. The server inspects real world structures at validation.
 *
 * World-space translucent schematic ghosts are not present in this slice.
 */
public final class CivCraftBlueprintScreen extends Screen {
    private final Screen parent;

    public CivCraftBlueprintScreen(Screen parent) {
        super(Component.literal("CivCraft — схема постройки лагеря"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        int x = width / 2 - 155;
        int y = Math.max(32, height / 2 - 110);

        addRenderableWidget(Button.builder(
                Component.literal("Шаг 1 — физический центр лагеря"),
                b -> {}).bounds(x, y, 310, 20).build()).active = false;
        addRenderableWidget(Button.builder(
                Component.literal("Шаг 2 — 3 укрытых спальни с кроватями"),
                b -> {}).bounds(x, y + 25, 310, 20).build()).active = false;
        addRenderableWidget(Button.builder(
                Component.literal("Шаг 3 — склад: сундук и минимум 16 еды"),
                b -> {}).bounds(x, y + 50, 310, 20).build()).active = false;
        addRenderableWidget(Button.builder(
                Component.literal("Шаг 4 — мастерская: верстак и печь"),
                b -> {}).bounds(x, y + 75, 310, 20).build()).active = false;
        addRenderableWidget(Button.builder(
                Component.literal("Шаг 5 — ферма: 4 грядки и компостер"),
                b -> {}).bounds(x, y + 100, 310, 20).build()).active = false;

        addRenderableWidget(Button.builder(Component.literal("Проверить построенное"),
                b -> {
                    Minecraft game = Minecraft.getInstance();
                    if (game.getConnection() != null)
                        game.getConnection().sendCommand("civcraft camp plan");
                }).bounds(x, y + 132, 310, 20).build());

        addRenderableWidget(Button.builder(Component.literal("Назад к управлению"),
                b -> onClose()).bounds(x, y + 158, 310, 20).build());
    }

    @Override
    public void onClose() {
        Minecraft.getInstance().gui.setScreen(parent);
    }
}
